import { useState } from 'react';
import './Login.css';

const ADMIN_PW  = '170417';
const VIEWER_PW = 'pfcpfc1!';

export default function Login({ onLogin }) {
  const [pw, setPw]       = useState('');
  const [error, setError] = useState('');
  const [show, setShow]   = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (pw === ADMIN_PW) {
      onLogin('admin');
    } else if (pw === VIEWER_PW) {
      onLogin('viewer');
    } else {
      setError('비밀번호가 올바르지 않습니다.');
      setPw('');
    }
  };

  return (
    <div className="login-wrap">
      <div className="login-card">
        <div className="login-logo">PF Chang's</div>
        <div className="login-title">브랜드 매출 분석 대시보드</div>
        <form onSubmit={handleSubmit} className="login-form" autoComplete="off">
          <div style={{ position: 'relative' }}>
            <input
              type={show ? 'text' : 'password'}
              placeholder="비밀번호를 입력하세요"
              value={pw}
              onChange={(e) => { setPw(e.target.value); setError(''); }}
              className="login-input"
              autoComplete="new-password"
              autoFocus
              style={{ paddingRight: 56 }}
            />
            <button
              type="button"
              onClick={() => setShow(s => !s)}
              style={{
                position: 'absolute', right: 10, top: '50%',
                transform: 'translateY(-50%)',
                background: 'none', border: 'none', cursor: 'pointer',
                color: '#6b7280', fontSize: 12, padding: '2px 4px'
              }}
            >
              {show ? '숨기기' : '표시'}
            </button>
          </div>
          {pw.length > 0 && (
            <div style={{ fontSize: 11, color: '#9ca3af', marginTop: 4, textAlign: 'right' }}>
              {pw.length}자 입력됨
            </div>
          )}
          {error && <div className="login-error">{error}</div>}
          <button type="submit" className="login-btn">로그인</button>
        </form>
        <div className="login-hint">본사 담당자 전용 시스템</div>
        <div style={{ fontSize: 10, color: '#d1d5db', marginTop: 8 }}>v2504h</div>
      </div>
    </div>
  );
}
