import * as XLSX from 'xlsx';

/**
 * 영업정보 .xls 파일 파서
 * 파일명 형식: YYYY-MM.xls
 * 시트: 사업장별 일별 매출/고객수/영수건수/영수단가 데이터
 */

const STORE_MAP = {
  '피에프창롯데월드몰점': '잠실',
  '피에프창신세계대구점': '대구',
  '피에프창서초점': '서초',
  '피에프창센텀시티몰점': '센텀',
  '피에프창신세계광주점': '광주',
  '피에프창신세계사우스시티': '사우스시티',
  '피에프창용산아이파크몰점': '용산',
  '피에프창코엑스몰점': '코엑스',
  '[폐점]피에프창타임스퀘어점': '타임스퀘어',
};

function mapStore(name) {
  return STORE_MAP[String(name).trim()] || String(name).trim();
}

function parseDate(dateStr) {
  // '2026-01-01(목)' → '2026-01-01'
  if (!dateStr) return null;
  const m = String(dateStr).match(/(\d{4}-\d{2}-\d{2})/);
  return m ? m[1] : null;
}

function isWeekendFromStr(dateStr) {
  if (!dateStr) return false;
  // '(토)' 또는 '(일)' 포함 시 주말
  if (String(dateStr).match(/\((토|일)\)/)) return true;
  const date = parseDate(dateStr);
  if (!date) return false;
  const dow = new Date(date).getDay();
  return dow === 0 || dow === 6;
}

function parseNum(val) {
  if (val === null || val === undefined || val === '') return 0;
  if (typeof val === 'number') return Math.round(val * 1000) / 1000;
  const n = parseFloat(String(val).replace(/,/g, ''));
  return isNaN(n) ? 0 : n;
}

/**
 * 단일 영업정보 .xls 파일 파싱
 * dailyOp 항목:
 *   { date, isWeekend,
 *     sales, guests, txCount,           ← 계(총계)
 *     lunchSales, lunchGuests, lunchTxCount,   ← 점심
 *     dinnerSales, dinnerGuests, dinnerTxCount  ← 저녁
 *   }
 */
export function parseOpInfoFile(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target.result);
        const workbook = XLSX.read(data, { type: 'array' });
        const sheet = workbook.Sheets[workbook.SheetNames[0]];
        const rows = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: null });

        const baseName = file.name.replace(/\.xls$/i, '');
        const parts = baseName.split('-');
        const year = parts[0];
        const month = parts[1];

        if (!year || !month) {
          reject(new Error(`파일명 형식 오류 (YYYY-MM.xls): ${file.name}`));
          return;
        }

        // { 'store|date' → dayData }
        const tempDayMap = {};
        let lastDateRaw = null;

        for (let r = 2; r < rows.length; r++) {
          const row = rows[r];
          if (!row) continue;

          const storeName = row[1];
          const dateRaw = row[2];
          const division = String(row[3] || '').trim();

          if (!['계', '점심', '저녁'].includes(division)) continue;
          if (!storeName || String(storeName).includes('총계')) continue;

          const store = mapStore(storeName);

          // 날짜: 일부 행은 dateRaw가 null일 수 있어 마지막 유효값 유지
          if (dateRaw) lastDateRaw = dateRaw;
          const date = parseDate(dateRaw || lastDateRaw);
          if (!date) continue;

          const dayKey = `${store}|${date}`;
          if (!tempDayMap[dayKey]) {
            tempDayMap[dayKey] = {
              date,
              isWeekend: isWeekendFromStr(dateRaw || lastDateRaw || ''),
              store,
              sales: 0, guests: 0, txCount: 0,
              avgPerGuest: 0, avgPerTx: 0, txGuestRatio: 0,
              lunchSales: 0, lunchGuests: 0, lunchTxCount: 0,
              dinnerSales: 0, dinnerGuests: 0, dinnerTxCount: 0,
            };
          }

          const entry = tempDayMap[dayKey];
          const s = parseNum(row[4]);
          const g = parseNum(row[6]);
          const t = parseNum(row[10]);

          if (division === '계') {
            entry.sales = s;
            entry.guests = g;
            entry.txCount = t;
            entry.avgPerGuest = parseNum(row[8]);
            entry.avgPerTx = parseNum(row[12]);
            entry.txGuestRatio = parseNum(row[14]);
          } else if (division === '점심') {
            entry.lunchSales = s;
            entry.lunchGuests = g;
            entry.lunchTxCount = t;
          } else if (division === '저녁') {
            entry.dinnerSales = s;
            entry.dinnerGuests = g;
            entry.dinnerTxCount = t;
          }
        }

        // store별 그룹핑
        const storeMap = {};
        for (const dayData of Object.values(tempDayMap)) {
          const { store, ...rest } = dayData;
          const key = `op-${store}-${year}-${month}`;
          if (!storeMap[store]) {
            storeMap[store] = { store, year, month, key, dailyOp: [] };
          }
          storeMap[store].dailyOp.push(rest);
        }

        Object.values(storeMap).forEach((rec) => {
          rec.dailyOp.sort((a, b) => a.date.localeCompare(b.date));
        });

        resolve(Object.values(storeMap));
      } catch (err) {
        reject(new Error(`영업정보 파싱 오류 (${file.name}): ${err.message}`));
      }
    };

    reader.onerror = () => reject(new Error(`파일 읽기 실패: ${file.name}`));
    reader.readAsArrayBuffer(file);
  });
}

export async function parseMultipleOpInfoFiles(files) {
  const results = [];
  const errors = [];

  for (const file of files) {
    try {
      const fileResults = await parseOpInfoFile(file);
      results.push(...fileResults);
    } catch (err) {
      errors.push(err.message);
    }
  }

  return { results, errors };
}
