import { useState, useMemo } from 'react';
import {
  LineChart, Line, BarChart, Bar, XAxis, YAxis, CartesianGrid,
  Tooltip, Legend, ResponsiveContainer
} from 'recharts';
import { filterData, formatKRW, formatShort, STORE_ORDER } from '../utils/calcMetrics';
import './StoreDetail.css';

export default function StoreDetail({ allData, opData, filters }) {
  const stores = useMemo(() => {
    const all = [...new Set(allData.map((d) => d.store))];
    return all.sort((a, b) => STORE_ORDER.indexOf(a) - STORE_ORDER.indexOf(b));
  }, [allData]);

  const [selectedStore, setSelectedStore] = useState(stores[0] || '');

  // 선택된 매장 월별 데이터
  const monthlyData = useMemo(() => {
    if (!selectedStore) return [];
    const filtered = filterData(allData, { ...filters, stores: [selectedStore] });
    const monthMap = {};

    filtered.forEach((d) => {
      const key = `${d.year}-${String(d.month).padStart(2, '0')}`;
      if (!monthMap[key]) {
        monthMap[key] = { yearMonth: key, year: d.year, month: d.month, sales: 0, txCount: 0 };
      }
      monthMap[key].sales += d.totalSales || 0;
      monthMap[key].txCount += d.totalTxCount || 0;
    });

    return Object.values(monthMap).sort((a, b) => a.yearMonth.localeCompare(b.yearMonth));
  }, [allData, filters, selectedStore]);

  // YoY 비교 (같은 월)
  const yoyData = useMemo(() => {
    if (!selectedStore || monthlyData.length < 2) return [];
    
    const byMonth = {};
    monthlyData.forEach((m) => {
      const month = m.month;
      if (!byMonth[month]) byMonth[month] = [];
      byMonth[month].push(m);
    });

    const result = [];
    Object.entries(byMonth).forEach(([month, data]) => {
      if (data.length >= 2) {
        const sorted = data.sort((a, b) => a.year - b.year);
        const current = sorted[sorted.length - 1];
        const previous = sorted[sorted.length - 2];
        result.push({
          month: `${current.year}년 ${month}월`,
          current: current.sales,
          previous: previous.sales,
        });
      }
    });

    return result;
  }, [monthlyData, selectedStore]);

  // 일별 데이터
  const dailyData = useMemo(() => {
    if (!selectedStore) return [];
    const filtered = filterData(allData, { ...filters, stores: [selectedStore] });
    const dayMap = {};

    filtered.forEach((file) => {
      file.dailyTotals.forEach((day) => {
        if (!dayMap[day.date]) {
          dayMap[day.date] = { date: day.date, sales: 0, txCount: 0 };
        }
        dayMap[day.date].sales += day.sales || 0;
        dayMap[day.date].txCount += day.txCount || 0;
      });
    });

    return Object.values(dayMap)
      .sort((a, b) => a.date.localeCompare(b.date))
      .map((d) => ({
        ...d,
        dateDisplay: d.date.slice(5),
      }))
      .slice(-30); // 최근 30일
  }, [allData, filters, selectedStore]);

  // TOP 10 상품
  const topProducts = useMemo(() => {
    if (!selectedStore) return [];
    const filtered = filterData(allData, { ...filters, stores: [selectedStore] });
    const prodMap = {};

    filtered.forEach((file) => {
      file.products.forEach((prod) => {
        const key = prod.code;
        if (!prodMap[key]) {
          prodMap[key] = {
            code: prod.code,
            name: prod.name,
            totalQty: 0,
            totalSales: 0,
          };
        }
        prodMap[key].totalQty += prod.totalQty || 0;
        prodMap[key].totalSales += prod.totalSales || 0;
      });
    });

    return Object.values(prodMap)
      .sort((a, b) => b.totalSales - a.totalSales)
      .slice(0, 10);
  }, [allData, filters, selectedStore]);

  // 영업정보 KPI
  const opKpis = useMemo(() => {
    if (!selectedStore || !opData.length) return null;
    const storeOp = opData.filter((d) => d.store === selectedStore && (!filters.year || d.year === filters.year));
    if (!storeOp.length) return null;

    let totalGuests = 0, totalTx = 0, totalSalesOp = 0;
    let lunchGuests = 0, dinnerGuests = 0;
    let lunchSales = 0, dinnerSales = 0;

    storeOp.forEach((d) => {
      d.dailyOp.forEach((day) => {
        totalGuests += day.guests || 0;
        totalTx += day.txCount || 0;
        totalSalesOp += day.sales || 0;
        lunchGuests += day.lunchGuests || 0;
        dinnerGuests += day.dinnerGuests || 0;
        lunchSales += day.lunchSales || 0;
        dinnerSales += day.dinnerSales || 0;
      });
    });

    return {
      totalGuests,
      totalTx,
      totalSalesOp,
      avgPerTx: totalTx > 0 ? totalSalesOp / totalTx : 0,
      avgPerGuest: totalGuests > 0 ? totalSalesOp / totalGuests : 0,
      lunchSales,
      dinnerSales,
      lunchGuests,
      dinnerGuests,
    };
  }, [selectedStore, opData, filters]);

  if (!selectedStore) return <div className="daily-empty">매장을 선택해주세요.</div>;

  return (
    <div className="store-detail">
      {/* 매장 선택 */}
      <div className="store-selector">
        {stores.map((store) => (
          <button
            key={store}
            className={`store-btn ${selectedStore === store ? 'active' : ''}`}
            onClick={() => setSelectedStore(store)}
          >
            {store}
          </button>
        ))}
      </div>

      {/* 월별 추이 */}
      {monthlyData.length > 0 && (
        <div className="chart-card">
          <div className="chart-title">{selectedStore} - 월별 매출 추이</div>
          <ResponsiveContainer width="100%" height={280}>
            <LineChart data={monthlyData} margin={{ top: 10, right: 20, left: 20, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
              <XAxis dataKey="yearMonth" tick={{ fontSize: 11 }} />
              <YAxis tickFormatter={formatShort} tick={{ fontSize: 11 }} />
              <Tooltip formatter={(v) => [`${formatKRW(v)}원`, '매출']} />
              <Legend />
              <Line type="monotone" dataKey="sales" stroke="#0d2258" strokeWidth={2} dot={{ r: 4 }} name="매출" />
            </LineChart>
          </ResponsiveContainer>
        </div>
      )}

      {/* YoY 비교 */}
      {yoyData.length > 0 && (
        <div className="chart-card">
          <div className="chart-title">{selectedStore} - 월별 전년 대비</div>
          <ResponsiveContainer width="100%" height={260}>
            <BarChart data={yoyData} margin={{ top: 10, right: 20, left: 10, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
              <XAxis dataKey="month" tick={{ fontSize: 11 }} angle={-30} textAnchor="end" height={60} />
              <YAxis tickFormatter={formatShort} tick={{ fontSize: 11 }} />
              <Tooltip formatter={(v) => [`${formatKRW(v)}원`, '']} />
              <Legend />
              <Bar dataKey="previous" fill="#d1d5db" name="전년" />
              <Bar dataKey="current" fill="#1d4ed8" name="금년" />
            </BarChart>
          </ResponsiveContainer>
        </div>
      )}

      {/* 일별 추이 (최근 30일) */}
      {dailyData.length > 0 && (
        <div className="chart-card">
          <div className="chart-title">{selectedStore} - 일별 추이 (최근 30일)</div>
          <ResponsiveContainer width="100%" height={260}>
            <LineChart data={dailyData} margin={{ top: 10, right: 20, left: 20, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
              <XAxis dataKey="dateDisplay" tick={{ fontSize: 10 }} interval={Math.floor(dailyData.length / 8)} />
              <YAxis tickFormatter={formatShort} tick={{ fontSize: 11 }} />
              <Tooltip formatter={(v) => [`${formatKRW(v)}원`, '매출']} />
              <Line type="monotone" dataKey="sales" stroke="#0d2258" strokeWidth={2} dot={false} name="매출" />
            </LineChart>
          </ResponsiveContainer>
        </div>
      )}

      {/* 영업정보 KPI */}
      {opKpis && (
        <div className="kpi-grid">
          <div className="kpi-card" style={{ borderTopColor: '#0d2258' }}>
            <div className="kpi-label">총 고객수</div>
            <div className="kpi-value" style={{ color: '#0d2258' }}>{formatKRW(opKpis.totalGuests)}명</div>
          </div>
          <div className="kpi-card" style={{ borderTopColor: '#1d4ed8' }}>
            <div className="kpi-label">영수건수</div>
            <div className="kpi-value" style={{ color: '#1d4ed8' }}>{formatKRW(opKpis.totalTx)}건</div>
          </div>
          <div className="kpi-card" style={{ borderTopColor: '#7c3aed' }}>
            <div className="kpi-label">영수단가</div>
            <div className="kpi-value" style={{ color: '#7c3aed' }}>{formatKRW(Math.round(opKpis.avgPerTx))}원</div>
          </div>
          <div className="kpi-card" style={{ borderTopColor: '#0f766e' }}>
            <div className="kpi-label">객단가</div>
            <div className="kpi-value" style={{ color: '#0f766e' }}>{formatKRW(Math.round(opKpis.avgPerGuest))}원</div>
          </div>
        </div>
      )}

      {/* TOP 10 상품 */}
      {topProducts.length > 0 && (
        <div className="chart-card">
          <div className="chart-title">{selectedStore} - TOP 10 상품</div>
          <table className="data-table">
            <thead>
              <tr>
                <th>순위</th>
                <th>상품명</th>
                <th>판매량</th>
                <th>매출</th>
              </tr>
            </thead>
            <tbody>
              {topProducts.map((p, idx) => (
                <tr key={p.code}>
                  <td style={{ textAlign: 'center', fontWeight: 600 }}>
                    {idx === 0 ? '🥇' : idx === 1 ? '🥈' : idx === 2 ? '🥉' : `${idx + 1}`}
                  </td>
                  <td className="td-store">{p.name}</td>
                  <td className="td-num">{p.totalQty}개</td>
                  <td className="td-num">{formatKRW(p.totalSales)}원</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* 점심/저녁 비교 */}
      {opKpis && (opKpis.lunchSales > 0 || opKpis.dinnerSales > 0) && (
        <div className="chart-grid-2">
          <div className="chart-card">
            <div className="chart-title">점심/저녁 매출</div>
            <ResponsiveContainer width="100%" height={240}>
              <BarChart
                data={[
                  { time: '점심', sales: opKpis.lunchSales, guests: opKpis.lunchGuests },
                  { time: '저녁', sales: opKpis.dinnerSales, guests: opKpis.dinnerGuests },
                ]}
                margin={{ top: 10, right: 20, left: 10, bottom: 5 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                <XAxis dataKey="time" tick={{ fontSize: 12 }} />
                <YAxis tickFormatter={formatShort} tick={{ fontSize: 11 }} />
                <Tooltip formatter={(v) => [`${formatKRW(v)}원`, '']} />
                <Bar dataKey="sales" fill="#d97706" name="매출" />
              </BarChart>
            </ResponsiveContainer>
          </div>
          <div className="chart-card">
            <div className="chart-title">점심/저녁 고객수</div>
            <ResponsiveContainer width="100%" height={240}>
              <BarChart
                data={[
                  { time: '점심', sales: opKpis.lunchSales, guests: opKpis.lunchGuests },
                  { time: '저녁', sales: opKpis.dinnerSales, guests: opKpis.dinnerGuests },
                ]}
                margin={{ top: 10, right: 20, left: 10, bottom: 5 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                <XAxis dataKey="time" tick={{ fontSize: 12 }} />
                <YAxis tickFormatter={(v) => v.toLocaleString()} tick={{ fontSize: 11 }} />
                <Tooltip formatter={(v) => [`${v.toLocaleString()}명`, '']} />
                <Bar dataKey="guests" fill="#1d4ed8" name="고객수" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      )}
    </div>
  );
}
